needles=['linesegarray','lineSegArray','LineSegArray','lineseg','lineSeg','LineSeg']
for base,_,files in os.walk(root):
    for fn in files:
        if not fn.endswith('.xml'):
            continue
        p=os.path.join(base,fn)
        s=open(p,'r',encoding='utf-8',errors='replace').read()
        if any(n in s for n in needles):
            print('FOUND layout-cache tokens in', p)
            for n in needles:
                if n in s:
                    print('  contains:', n)
